import json, glob, time
import numpy as np
import pandas as pd
from pathlib import Path
from src.rsa_open.loop.fitting import _read, read_corpus
from src.rsa_open.fit import TheoryModel
from src.rsa_open.loop.critique import simulate_outcomes

jsons = glob.glob('_runs/chain_0/experiment1/loop/.fit_cache/rsa_l2_singleton_feat_color_valence_l0.*.json')
fitted = _read(Path(jsons[0][:-4] + 'nc'), Path(jsons[0]))
theory = TheoryModel(Path('_runs/chain_0/experiment1/loop/models/rsa_l2_singleton_feat_color_valence_l0.py'))
blocks = read_corpus(Path('_runs/chain_0/experiment1/loop/corpus.json'))
exp1_block = next(b for b in blocks if b.name == 'exp1')
sims = simulate_outcomes(theory, fitted, exp1_block, n_replicates=100, seed=42)

with open('_runs/chain_0/experiment1/loop/data/exp1.jsonl') as f:
    obs_records = [json.loads(line) for line in f]

rows = [{'trial': r['trial'], 'unit': r['unit'], 'source': r['source'],
         'objects': json.dumps(r['objects']), 'heard': np.nan if r['heard'] is None else r['heard'],
         'points': json.dumps(r['response']['points'])} for r in obs_records]
human_df = pd.DataFrame(rows)
model_dfs = []
for rep in sims:
    df_rep = human_df.copy()
    df_rep['points'] = rep
    model_dfs.append(df_rep)

# Define all 8 statistics exactly as they will be written:

# 1. scalar_implicature_points_on_full_feature_competitor
def stat1(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if pd.isna(sc['heard']):
            continue
        h = int(sc['heard'])
        objs = json.loads(sc['objects'])
        comp = [i for i, o in enumerate(objs) if o[h] == 1]
        non_comp = [i for i, o in enumerate(objs) if o[h] == 0]
        if len(comp) == 2 and len(non_comp) >= 2:
            comp_lens = sorted([sum(objs[i]) for i in comp])
            if comp_lens == [1, 3]:
                nc_objs = [objs[i] for i in non_comp]
                if len(set(tuple(x) for x in nc_objs)) == 1:
                    idx_3 = [i for i in comp if sum(objs[i]) == 3][0]
                    target_scenes[(sc['objects'], sc['heard'])] = idx_3
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idx in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'] == h_val)]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += pts[idx]
            cnt += 1
    return float(tot / max(cnt, 1))

# 2. points_on_singleton_competitor_with_duplicate_targets
def stat2(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if pd.isna(sc['heard']):
            continue
        h = int(sc['heard'])
        objs = json.loads(sc['objects'])
        comp = [i for i, o in enumerate(objs) if o[h] == 1]
        dups = [i for i in comp if objs.count(objs[i]) == 2 and sum(objs[i]) == 1]
        sings = [i for i in comp if objs.count(objs[i]) == 1 and sum(objs[i]) == 2]
        if len(dups) == 2 and len(sings) == 1:
            target_scenes[(sc['objects'], sc['heard'])] = sings[0]
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idx in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'] == h_val)]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += pts[idx]
            cnt += 1
    return float(tot / max(cnt, 1))

# 3. points_on_minimal_targets_when_word_is_universal
def stat3(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if pd.isna(sc['heard']):
            continue
        h = int(sc['heard'])
        objs = json.loads(sc['objects'])
        if all(o[h] == 1 for o in objs):
            mins = [i for i, o in enumerate(objs) if sum(o) == 1 and objs.count(o) > 1]
            multis = [i for i, o in enumerate(objs) if sum(o) > 1 and objs.count(o) == 1]
            if len(mins) == 2 and len(multis) == 2:
                target_scenes[(sc['objects'], sc['heard'])] = mins
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idxs in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'] == h_val)]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += sum(pts[i] for i in idxs)
            cnt += 1
    return float(tot / max(cnt, 1))

# 4. prior_points_partial_minus_full_feature_singleton
def stat4(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if not pd.isna(sc['heard']):
            continue
        objs = json.loads(sc['objects'])
        empties = [i for i, o in enumerate(objs) if sum(o) == 0]
        partial = [i for i, o in enumerate(objs) if 1 <= sum(o) < len(o) and objs.count(o) == 1]
        full = [i for i, o in enumerate(objs) if sum(o) == len(o) and objs.count(o) == 1]
        if len(empties) >= 2 and len(partial) == 1 and len(full) == 1:
            target_scenes[(sc['objects'], sc['heard'])] = (partial[0], full[0])
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), (i_part, i_full) in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'].isna())]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += (pts[i_part] - pts[i_full])
            cnt += 1
    return float(tot / max(cnt, 1))

# 5. prior_points_on_empty_singleton_with_full_duplicates
def stat5(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if not pd.isna(sc['heard']):
            continue
        objs = json.loads(sc['objects'])
        empties = [i for i, o in enumerate(objs) if sum(o) == 0]
        fulls = [i for i, o in enumerate(objs) if sum(o) == len(o)]
        if len(empties) == 1 and len(fulls) == len(objs) - 1:
            target_scenes[(sc['objects'], sc['heard'])] = empties[0]
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idx in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'].isna())]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += pts[idx]
            cnt += 1
    return float(tot / max(cnt, 1))

# 6. duplicate_targets_minus_singleton_competitor_points
def stat6(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if pd.isna(sc['heard']):
            continue
        h = int(sc['heard'])
        objs = json.loads(sc['objects'])
        comp = [i for i, o in enumerate(objs) if o[h] == 1]
        dups = [i for i in comp if objs.count(objs[i]) == 2 and sum(objs[i]) == 2]
        sings = [i for i in comp if objs.count(objs[i]) == 1 and sum(objs[i]) == 3]
        if len(dups) == 2 and len(sings) == 1:
            target_scenes[(sc['objects'], sc['heard'])] = (dups, sings[0])
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), (d_idxs, s_idx) in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'] == h_val)]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += (sum(pts[i] for i in d_idxs) - pts[s_idx])
            cnt += 1
    return float(tot / max(cnt, 1))

# 7. points_on_minimal_singleton_with_duplicate_competitors
def stat7(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if pd.isna(sc['heard']):
            continue
        h = int(sc['heard'])
        objs = json.loads(sc['objects'])
        if all(o[h] == 1 for o in objs):
            min_sings = [i for i, o in enumerate(objs) if sum(o) == 1 and objs.count(o) == 1]
            dup_comps = [i for i, o in enumerate(objs) if sum(o) > 1 and objs.count(o) > 1]
            if len(min_sings) == 1 and len(dup_comps) >= 2:
                target_scenes[(sc['objects'], sc['heard'])] = min_sings[0]
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idx in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'] == h_val)]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += pts[idx]
            cnt += 1
    return float(tot / max(cnt, 1))

# 8. prior_points_empty_object_with_partial_duplicates
def stat8(df):
    scenes = df[['objects', 'heard']].drop_duplicates()
    target_scenes = {}
    for _, sc in scenes.iterrows():
        if not pd.isna(sc['heard']):
            continue
        objs = json.loads(sc['objects'])
        empties = [i for i, o in enumerate(objs) if sum(o) == 0]
        dups_1 = [i for i, o in enumerate(objs) if sum(o) == 1 and objs.count(o) == 2]
        sings_2 = [i for i, o in enumerate(objs) if sum(o) == 2 and objs.count(o) == 1]
        if len(empties) == 1 and len(dups_1) == 2 and len(sings_2) == 1:
            target_scenes[(sc['objects'], sc['heard'])] = empties[0]
    if not target_scenes:
        return 0.0
    tot, cnt = 0.0, 0
    for (obj_str, h_val), idx in target_scenes.items():
        sub_pts = df[(df['objects'] == obj_str) & (df['heard'].isna())]['points']
        for p_str in sub_pts:
            pts = json.loads(p_str) if isinstance(p_str, str) else p_str
            tot += pts[idx]
            cnt += 1
    return float(tot / max(cnt, 1))

stats = [
    (stat1, 'scalar_implicature_points_on_full_feature_competitor'),
    (stat2, 'points_on_singleton_competitor_with_duplicate_targets'),
    (stat3, 'points_on_minimal_targets_when_word_is_universal'),
    (stat4, 'prior_points_partial_minus_full_feature_singleton'),
    (stat5, 'prior_points_on_empty_singleton_with_full_duplicates'),
    (stat6, 'duplicate_targets_minus_singleton_competitor_points'),
    (stat7, 'points_on_minimal_singleton_with_duplicate_competitors'),
    (stat8, 'prior_points_empty_object_with_partial_duplicates')
]

for fn, name in stats:
    t0 = time.time()
    obs = fn(human_df)
    nulls = np.array([fn(m) for m in model_dfs])
    t1 = time.time()
    z = (obs - np.mean(nulls)) / (np.std(nulls) + 1e-8)
    p = min(1.0, 2.0 * min((np.sum(nulls >= obs) + 1)/(len(nulls)+1), (np.sum(nulls <= obs) + 1)/(len(nulls)+1)))
    per_call = (t1 - t0) / (len(model_dfs) + 1)
    print(f'{name:<55}: obs={obs:6.3f}, null={np.mean(nulls):6.3f}, z={z:6.2f}, p={p:6.4f}, time/call={per_call*1000:.2f}ms')
"

